select json_unquote(json_extract(hints_json,'$.ab_experiment.experiment_id')) as exp_id, json_unquote(json_extract(hints_json,'$.ab_experiment.factor')) as factor, json_unquote(json_extract(hints_json,'$.ab_experiment.role')) as role, id as run_id, status, json_unquote(json_extract(hints_json,'$.knowledge_mode')) as kmode, challenge_id, started_at, max_total_runtime_seconds from solve_runs where json_extract(hints_json,'$.ab_experiment.experiment_id') is not null order by started_at desc limit 30;
select id, challenge_id, engine_type, model_config_id, status, solver_mode, started_at from solve_runs order by started_at desc limit 20;
